/** Public entry point — the only module consumers/docs should import from. */

export {
  DataGridStatusBar,
  type DataGridStatusBarProps,
  type StatusBarAggregate,
} from "./status-bar";
export { useDataGridSelectionStats } from "./use-data-grid-selection-stats";
export { MAX_STATUS_CELLS, type SelectionStats } from "./compute-selection-stats";

"use client";

import { useMemo, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import {
  DEFAULT_LABELS,
  useDataGridCellTypes,
  useDataGridLabels,
  useDataGridVisibleColumns,
  type DataGridStatusBarLabels,
} from "@/registry/default/components/data-grid/data-grid";
import { MAX_STATUS_CELLS } from "./compute-selection-stats";
import { useDataGridSelectionStats } from "./use-data-grid-selection-stats";

/** One of the aggregates the bar can show. */
export type StatusBarAggregate = "count" | "sum" | "avg" | "min" | "max";

/** Props for {@link DataGridStatusBar}. */
export type DataGridStatusBarProps = {
  /** Which aggregates to show, and in which order. Default: all five, `count`, `sum`, `avg`, `min`, `max`. */
  aggregates?: readonly StatusBarAggregate[];
  /**
   * Formats the shown aggregate values. When omitted, the single-column rule applies: if every
   * numeric cell comes from one column, its `toDisplayText` formats sum/avg/min/max (a `number`
   * column's `options.format` shows currency); otherwise `Intl.NumberFormat(locale, { maximumFractionDigits: 4 })`.
   */
  formatValue?: (value: number, aggregate: StatusBarAggregate) => string;
  /** Locale for the default number format. Default `"en-US"` (the date type's SSR-safe default). */
  locale?: string;
  /** i18n overrides for this bar's strings, merged over `labels.statusBar`. */
  labels?: Partial<DataGridStatusBarLabels>;
  className?: string;
  /** Extra items, rendered after the aggregates. */
  children?: ReactNode;
};

const DEFAULT_AGGREGATES: readonly StatusBarAggregate[] = ["count", "sum", "avg", "min", "max"];

/**
 * Aggregate bar for the selected cells: count of non-empty cells plus sum/avg/min/max of numeric
 * cells, computed by {@link useDataGridSelectionStats}. Place it inside `DataGridProvider`, next
 * to `DataGridRoot`, like the pagination bar. Renders nothing while fewer than 2 cells are
 * selected.
 */
export function DataGridStatusBar({
  aggregates = DEFAULT_AGGREGATES,
  formatValue,
  locale = "en-US",
  labels,
  className,
  children,
}: DataGridStatusBarProps) {
  const stats = useDataGridSelectionStats();
  const storeLabels = useDataGridLabels();
  const mergedLabels = { ...DEFAULT_LABELS.statusBar, ...storeLabels.statusBar, ...labels };
  const visibleColumns = useDataGridVisibleColumns();
  const cellTypes = useDataGridCellTypes();
  const fallbackFormat = useMemo(() => new Intl.NumberFormat(locale, { maximumFractionDigits: 4 }), [locale]);

  const displayText = useMemo(() => {
    if (stats.numericColumnId === null) return null;
    const column = visibleColumns.find((c) => c.id === stats.numericColumnId);
    const cellType = column ? (cellTypes[column.type ?? "text"] ?? cellTypes["text"]) : undefined;
    const toDisplayText = cellType?.toDisplayText;
    if (!column || !toDisplayText) return null;
    return (value: number) => toDisplayText(value, column.options);
  }, [stats.numericColumnId, visibleColumns, cellTypes]);

  if (stats.cells < 2) return null;

  const format = (value: number, aggregate: StatusBarAggregate) =>
    formatValue ? formatValue(value, aggregate) : aggregate !== "count" && displayText ? displayText(value) : fallbackFormat.format(value);

  return (
    <div
      role="status"
      aria-live="polite"
      aria-atomic="true"
      title={stats.approximate ? mergedLabels.approximate(MAX_STATUS_CELLS) : undefined}
      className={cn("flex flex-wrap items-center gap-x-3 gap-y-1 border-t border-border bg-background px-2 py-1.5 text-xs text-muted-foreground", className)}
    >
      {aggregates.map((aggregate) => {
        const value = aggregate === "count" ? stats.count : stats[aggregate];
        if (value === null) return null;
        return (
          <span key={aggregate}>
            <span className="text-muted-foreground">{mergedLabels[aggregate]}</span>{" "}
            <span className="tabular-nums text-foreground">
              {stats.approximate ? "≈" : ""}
              {format(value, aggregate)}
            </span>
          </span>
        );
      })}
      {children}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import {
  getCellValue,
  useDataGridCellTypes,
  useDataGridSelection,
  useDataGridSelector,
  useDataGridViewIndex,
  useDataGridVisibleColumns,
  type AnyColumnDef,
} from "@/registry/default/components/data-grid/data-grid";
import { selectionRects } from "@/registry/default/components/data-grid/data-grid-sdk";
import { computeSelectionStats, EMPTY_SELECTION_STATS, type SelectionStats } from "./compute-selection-stats";

/** Total rect area up to which the walk runs at once; above it, the settle timer defers it. */
export const IMMEDIATE_SELECTION_CELL_LIMIT = 5_000;
/** Trailing delay in ms before a large selection's walk runs, after the last selection change. */
export const SELECTION_STATS_SETTLE_MS = 150;

/**
 * Aggregates (count, sum, avg, min, max) over the selected cells, recomputed after the selection
 * settles: at once for up to {@link IMMEDIATE_SELECTION_CELL_LIMIT} cells, else on a
 * {@link SELECTION_STATS_SETTLE_MS} ms trailing timer. Stops at `MAX_STATUS_CELLS` and flags
 * `approximate`. See {@link computeSelectionStats} for the field semantics.
 */
export function useDataGridSelectionStats(): SelectionStats {
  const selection = useDataGridSelection();
  const viewIndex = useDataGridViewIndex();
  const visibleColumns = useDataGridVisibleColumns();
  const cellTypes = useDataGridCellTypes();
  const data = useDataGridSelector((s) => s.data);
  const [stats, setStats] = useState(EMPTY_SELECTION_STATS);

  useEffect(() => {
    const columns = visibleColumns as readonly AnyColumnDef[];
    const rects = selectionRects(selection, viewIndex.length, columns.length);
    let area = 0;
    for (const rect of rects) area += rect.width * rect.height;
    if (area === 0) {
      setStats(EMPTY_SELECTION_STATS);
      return;
    }
    const compute = () => {
      setStats(
        computeSelectionStats({
          rects,
          rowCount: viewIndex.length,
          colCount: columns.length,
          valueAt: (viewRow, viewCol) => {
            const dataRow = viewIndex[viewRow];
            const row = dataRow === undefined ? undefined : data[dataRow];
            if (row === undefined) return undefined;
            return getCellValue<unknown, AnyColumnDef>(row, columns[viewCol]!);
          },
          isEmptyAt: (viewCol, value) => {
            const column = columns[viewCol]!;
            const cellType = cellTypes[column.type ?? "text"] ?? cellTypes["text"]!;
            return cellType.isEmpty(value);
          },
          columnIdAt: (viewCol) => columns[viewCol]!.id,
        }),
      );
    };
    // ponytail: rect area is an upper bound on the union, so overlapping selections can defer to
    // the timer with a small real walk; an exact union count would cost the walk itself.
    if (area <= IMMEDIATE_SELECTION_CELL_LIMIT) {
      compute();
      return;
    }
    const timer = window.setTimeout(compute, SELECTION_STATS_SETTLE_MS);
    return () => window.clearTimeout(timer);
  }, [selection, viewIndex, visibleColumns, cellTypes, data]);

  return stats;
}

import type { GridRect } from "@/registry/default/components/data-grid/data-grid";

/** Walk cap for one status-bar aggregation, in counted cells (same cap as the clipboard's `MAX_COPY_CELLS`). */
export const MAX_STATUS_CELLS = 200_000;

export type SelectionStats = {
  /** Selected cells with a value, each counted once across overlapping rects. */
  cells: number;
  /** Cells whose column's cell type `isEmpty` is false. */
  count: number;
  /** Cells whose raw value is a finite number. */
  numeric: number;
  /** Neumaier-compensated sum of the numeric values; `null` when `numeric === 0`. */
  sum: number | null;
  avg: number | null;
  min: number | null;
  max: number | null;
  /** The single column id all numeric cells came from; `null` when they span several columns. */
  numericColumnId: string | null;
  /** The walk stopped at `maxCells` before seeing the whole selection. */
  approximate: boolean;
};

/** All-zero stats: nothing selected (also the hook's initial state). */
export const EMPTY_SELECTION_STATS: SelectionStats = {
  cells: 0,
  count: 0,
  numeric: 0,
  sum: null,
  avg: null,
  min: null,
  max: null,
  numericColumnId: null,
  approximate: false,
};

export type SelectionStatsInput = {
  /** The selection regions in apply order; a cell in two rects counts once. */
  rects: readonly GridRect[];
  /** Visible rows the rects index into (`viewIndex.length`). */
  rowCount: number;
  /** Visible columns the rects index into. */
  colCount: number;
  /** The cell value at a view position; `undefined` for an unloaded (lazy) hole. */
  valueAt: (viewRow: number, viewCol: number) => unknown;
  /** Whether `value` is empty for the column at `viewCol` (that column's cell type `isEmpty`). */
  isEmptyAt: (viewCol: number, value: unknown) => boolean;
  /** The id of the visible column at `viewCol`. */
  columnIdAt: (viewCol: number) => string;
  /** Stop the walk once `cells` reaches this (default {@link MAX_STATUS_CELLS}). */
  maxCells?: number;
};

export function computeSelectionStats(input: SelectionStatsInput): SelectionStats {
  const { rects, rowCount, colCount, valueAt, isEmptyAt, columnIdAt } = input;
  const maxCells = input.maxCells ?? MAX_STATUS_CELLS;
  const seen = new Set<number>();
  let cells = 0;
  let count = 0;
  let numeric = 0;
  let sum = 0;
  // Neumaier compensation term; the plain sum alone loses 0.1 + 0.2 = 0.30000000000000004.
  let compensation = 0;
  let min = Infinity;
  let max = -Infinity;
  let numericColumnId: string | null = null;
  let mixedColumns = false;
  let approximate = false;
  let stopped = false;

  for (const rect of rects) {
    if (stopped) break;
    const x1 = Math.min(rect.x + rect.width, colCount);
    const y1 = Math.min(rect.y + rect.height, rowCount);
    for (let y = Math.max(rect.y, 0); y < y1 && !stopped; y++) {
      for (let x = Math.max(rect.x, 0); x < x1; x++) {
        const key = y * colCount + x;
        if (seen.has(key)) continue;
        if (cells === maxCells) {
          // cap reached: the first `maxCells` cells are in, the rest is not read
          approximate = true;
          stopped = true;
          break;
        }
        seen.add(key);
        const value = valueAt(y, x);
        if (value === undefined) continue;
        cells += 1;
        if (!isEmptyAt(x, value)) count += 1;
        if (typeof value === "number" && Number.isFinite(value)) {
          numeric += 1;
          const t = sum + value;
          compensation += Math.abs(sum) >= Math.abs(value) ? (sum - t) + value : (value - t) + sum;
          sum = t;
          if (value < min) min = value;
          if (value > max) max = value;
          const id = columnIdAt(x);
          if (numericColumnId === null) numericColumnId = id;
          else if (numericColumnId !== id) mixedColumns = true;
        }
      }
    }
  }

  const total = sum + compensation;
  return {
    cells,
    count,
    numeric,
    sum: numeric > 0 ? total : null,
    avg: numeric > 0 ? total / numeric : null,
    min: numeric > 0 ? min : null,
    max: numeric > 0 ? max : null,
    numericColumnId: numeric > 0 && !mixedColumns ? numericColumnId : null,
    approximate,
  };
}
